create extension if not exists "pgcrypto";
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null, email text not null, phone text not null, requested_account_type text not null default 'demo' check (requested_account_type in ('demo','live')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.demo_accounts (user_id uuid primary key references auth.users(id) on delete cascade, virtual_cash numeric(14,2) not null default 10000.00, virtual_equity numeric(14,2) not null default 10000.00, created_at timestamptz not null default now());
create table if not exists public.demo_orders (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, symbol text not null, side text not null check (side in ('buy','sell')), quantity numeric(18,6) not null check (quantity > 0), simulated_price numeric(18,6) not null check (simulated_price > 0), stop_loss numeric(18,6), margin_multiplier integer not null default 1 check (margin_multiplier between 1 and 10), created_at timestamptz not null default now());
create table if not exists public.payout_preferences (user_id uuid primary key references auth.users(id) on delete cascade, method text not null check (method in ('bank','wallet')), account_holder_name text not null, provider_name text not null, account_last4 text not null check (char_length(account_last4)=4), updated_at timestamptz not null default now());
create table if not exists public.live_account_applications (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, planned_deposit numeric(14,2) not null check (planned_deposit>0), funding_source text not null, status text not null default 'pending_review' check (status in ('pending_review','approved','rejected')), created_at timestamptz not null default now());
alter table public.profiles enable row level security; alter table public.demo_accounts enable row level security; alter table public.demo_orders enable row level security; alter table public.payout_preferences enable row level security; alter table public.live_account_applications enable row level security;
create policy "Users read own profile" on public.profiles for select using (auth.uid()=id); create policy "Users update own profile" on public.profiles for update using (auth.uid()=id);
create policy "Users read own demo account" on public.demo_accounts for select using (auth.uid()=user_id); create policy "Users update own demo account" on public.demo_accounts for update using (auth.uid()=user_id);
create policy "Users manage own demo orders" on public.demo_orders for all using (auth.uid()=user_id) with check (auth.uid()=user_id);
create policy "Users manage own payout preference" on public.payout_preferences for all using (auth.uid()=user_id) with check (auth.uid()=user_id);
create policy "Users create own live application" on public.live_account_applications for insert with check (auth.uid()=user_id); create policy "Users read own live applications" on public.live_account_applications for select using (auth.uid()=user_id);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name,email,phone,requested_account_type) values(new.id,coalesce(new.raw_user_meta_data->>'full_name','New customer'),new.email,coalesce(new.raw_user_meta_data->>'phone',''),coalesce(new.raw_user_meta_data->>'requested_account_type','demo')); insert into public.demo_accounts(user_id) values(new.id); return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
